using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();

        await db.Database.MigrateAsync();

        // Create roles
        foreach (var role in new[] { "Dispatcher", "Customer" })
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }

        // Create demo dispatcher
        var dispatcher = await EnsureUserAsync(userManager, "dispatcher@shiptrack.com", "Dispatch1!", "Dispatcher");

        // Create demo customer
        var customer = await EnsureUserAsync(userManager, "customer@example.com", "Customer1!", "Customer");

        // Seed shipments if empty
        if (!await db.Shipments.AnyAsync())
        {
            var now = DateTime.UtcNow;
            db.Shipments.AddRange(
                new Shipment
                {
                    TrackingNumber = "ST-100001",
                    Origin = "New York, NY",
                    Destination = "Los Angeles, CA",
                    Status = ShipmentStatus.InTransit,
                    ShippedDate = now.AddDays(-3),
                    EstimatedDelivery = now.AddDays(2),
                    RecipientName = "Alice Johnson",
                    CustomerUserId = customer.Id,
                    Notes = "Fragile electronics"
                },
                new Shipment
                {
                    TrackingNumber = "ST-100002",
                    Origin = "Chicago, IL",
                    Destination = "Miami, FL",
                    Status = ShipmentStatus.Pending,
                    ShippedDate = now.AddDays(-1),
                    EstimatedDelivery = now.AddDays(4),
                    RecipientName = "Bob Smith",
                    CustomerUserId = customer.Id
                },
                new Shipment
                {
                    TrackingNumber = "ST-100003",
                    Origin = "Seattle, WA",
                    Destination = "Denver, CO",
                    Status = ShipmentStatus.Delivered,
                    ShippedDate = now.AddDays(-7),
                    EstimatedDelivery = now.AddDays(-2),
                    ActualDelivery = now.AddDays(-2),
                    RecipientName = "Carol White",
                    CustomerUserId = customer.Id
                },
                new Shipment
                {
                    TrackingNumber = "ST-100004",
                    Origin = "Houston, TX",
                    Destination = "Phoenix, AZ",
                    Status = ShipmentStatus.OutForDelivery,
                    ShippedDate = now.AddDays(-4),
                    EstimatedDelivery = now,
                    RecipientName = "Dave Brown"
                },
                new Shipment
                {
                    TrackingNumber = "ST-100005",
                    Origin = "Boston, MA",
                    Destination = "Atlanta, GA",
                    Status = ShipmentStatus.Delayed,
                    ShippedDate = now.AddDays(-5),
                    EstimatedDelivery = now.AddDays(3),
                    RecipientName = "Eve Davis",
                    Notes = "Weather delay in transit hub"
                },
                new Shipment
                {
                    TrackingNumber = "ST-100006",
                    Origin = "San Francisco, CA",
                    Destination = "Portland, OR",
                    Status = ShipmentStatus.PickedUp,
                    ShippedDate = now,
                    EstimatedDelivery = now.AddDays(2),
                    RecipientName = "Frank Miller",
                    CustomerUserId = customer.Id
                }
            );
            await db.SaveChangesAsync();
        }
    }

    private static async Task<ApplicationUser> EnsureUserAsync(
        UserManager<ApplicationUser> userManager, string email, string password, string role)
    {
        var user = await userManager.FindByEmailAsync(email);
        if (user is null)
        {
            user = new ApplicationUser { UserName = email, Email = email, EmailConfirmed = true };
            var result = await userManager.CreateAsync(user, password);
            if (!result.Succeeded)
                throw new Exception($"Failed to create {email}: {string.Join(", ", result.Errors.Select(e => e.Description))}");
        }
        if (!await userManager.IsInRoleAsync(user, role))
            await userManager.AddToRoleAsync(user, role);
        return user;
    }
}

