using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // GET all shipments — dispatchers see all, customers see only theirs
        group.MapGet("/", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var query = db.Shipments.AsNoTracking();

            if (!user.IsInRole("Dispatcher"))
            {
                var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
                query = query.Where(s => s.CustomerUserId == userId);
            }

            var shipments = await query.OrderByDescending(s => s.ShippedDate)
                .Select(s => ToDto(s))
                .ToListAsync();

            return TypedResults.Ok(shipments);
        });

        // GET single shipment by ID
        group.MapGet("/{id:int}", async Task<Results<Ok<ShipmentDto>, NotFound>> (int id, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var shipment = await db.Shipments.AsNoTracking().FirstOrDefaultAsync(s => s.Id == id);
            if (shipment is null)
                return TypedResults.NotFound();

            if (!user.IsInRole("Dispatcher"))
            {
                var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
                if (shipment.CustomerUserId != userId)
                    return TypedResults.NotFound();
            }

            return TypedResults.Ok(ToDto(shipment));
        });

        // GET track by tracking number (requires auth but any role)
        group.MapGet("/track/{trackingNumber}", async Task<Results<Ok<ShipmentDto>, NotFound>> (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.AsNoTracking()
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null
                ? TypedResults.NotFound()
                : TypedResults.Ok(ToDto(shipment));
        });

        // POST — dispatchers only
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async Task<Results<Created<ShipmentDto>, ValidationProblem>> (
            ShipmentDto dto, ApplicationDbContext db, UserManager<ApplicationUser> userManager) =>
        {
            var maxNumber = await db.Shipments.MaxAsync(s => (int?)s.Id) ?? 100000;
            var shipment = new Shipment
            {
                TrackingNumber = $"ST-{maxNumber + 1}",
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = ShipmentStatus.Pending,
                ShippedDate = DateTime.UtcNow,
                EstimatedDelivery = dto.EstimatedDelivery,
                RecipientName = dto.RecipientName,
                Notes = dto.Notes
            };

            if (!string.IsNullOrWhiteSpace(dto.CustomerEmail))
            {
                var customer = await userManager.FindByEmailAsync(dto.CustomerEmail);
                if (customer is not null)
                    shipment.CustomerUserId = customer.Id;
            }

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return TypedResults.Created($"/api/shipments/{shipment.Id}", ToDto(shipment));
        });

        // PUT status update — dispatchers only
        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async Task<Results<Ok<ShipmentDto>, NotFound>> (
            int id, StatusUpdateDto update, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return TypedResults.NotFound();

            shipment.Status = (ShipmentStatus)(int)update.Status;
            if (update.Status == Client.Models.ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;
            if (!string.IsNullOrWhiteSpace(update.Notes))
                shipment.Notes = update.Notes;

            await db.SaveChangesAsync();
            return TypedResults.Ok(ToDto(shipment));
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (Client.Models.ShipmentStatus)(int)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        Notes = s.Notes
    };
}

public record StatusUpdateDto(Client.Models.ShipmentStatus Status, string? Notes);

