@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h2>🚛 Dispatcher Dashboard</h2>
        <button class="btn btn-primary" @onclick="ToggleNewShipmentForm">
            @(showNewForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>

    @if (showNewForm)
    {
        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title">Create New Shipment</h5>
                <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="newShipmentForm">
                    <DataAnnotationsValidator />
                    <div class="row g-3">
                        <div class="col-md-6">
                            <label class="form-label">Origin</label>
                            <InputText class="form-control" @bind-Value="newShipment.Origin" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Destination</label>
                            <InputText class="form-control" @bind-Value="newShipment.Destination" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">Recipient Name</label>
                            <InputText class="form-control" @bind-Value="newShipment.RecipientName" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">Customer Email (optional)</label>
                            <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">Estimated Delivery</label>
                            <InputDate class="form-control" @bind-Value="newShipment.EstimatedDelivery" />
                        </div>
                        <div class="col-12">
                            <label class="form-label">Notes</label>
                            <InputText class="form-control" @bind-Value="newShipment.Notes" />
                        </div>
                        <div class="col-12">
                            <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                                @(isSubmitting ? "Creating..." : "Create Shipment")
                            </button>
                        </div>
                    </div>
                </EditForm>
                @if (!string.IsNullOrEmpty(formMessage))
                {
                    <div class="alert alert-info mt-3">@formMessage</div>
                }
            </div>
        </div>
    }

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or recipient..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="filterStatus">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-secondary" @onclick="LoadShipments">🔄 Refresh</button>
        </div>
    </div>

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else if (!FilteredShipments.Any())
    {
        <p class="text-muted">No shipments match the current filter.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><strong>@s.TrackingNumber</strong></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td>@s.RecipientName</td>
                            <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>
                                @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Returned)
                                {
                                    <select class="form-select form-select-sm d-inline-block w-auto"
                                            @onchange="(e) => UpdateStatus(s.Id, e)">
                                        <option value="">Update...</option>
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@((int)status)">@status</option>
                                        }
                                    </select>
                                }
                                else
                                {
                                    <span class="text-muted small">
                                        @(s.ActualDelivery.HasValue ? $"Delivered {s.ActualDelivery.Value:MMM dd}" : "—")
                                    </span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private bool showNewForm;
    private bool isSubmitting;
    private string? formMessage;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(filterText))
            {
                var f = filterText.Trim();
                if (!s.TrackingNumber.Contains(f, StringComparison.OrdinalIgnoreCase) &&
                    !s.Destination.Contains(f, StringComparison.OrdinalIgnoreCase) &&
                    !s.RecipientName.Contains(f, StringComparison.OrdinalIgnoreCase))
                    return false;
            }
            if (!string.IsNullOrEmpty(filterStatus) && Enum.TryParse<ShipmentStatus>(filterStatus, out var status))
            {
                if (s.Status != status)
                    return false;
            }
            return true;
        });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private void ToggleNewShipmentForm()
    {
        showNewForm = !showNewForm;
        formMessage = null;
        if (showNewForm)
            newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    }

    private async Task CreateShipment()
    {
        isSubmitting = true;
        formMessage = null;
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            formMessage = $"Shipment {created?.TrackingNumber} created successfully!";
            showNewForm = false;
            await LoadShipments();
        }
        else
        {
            formMessage = "Failed to create shipment. Please check all fields.";
        }
        isSubmitting = false;
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusValue))
        {
            var status = (ShipmentStatus)statusValue;
            await Http.PutAsJsonAsync($"/api/shipments/{id}/status",
                new { Status = status, Notes = (string?)null });
            await LoadShipments();
        }
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

