+        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
+    }
+
+    private void ToggleNewShipmentForm()
+    {
+        showNewForm = !showNewForm;
+        formMessage = null;
+        if (showNewForm)
+            newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
+    }
+
+    private async Task CreateShipment()
+    {
+        isSubmitting = true;
+        formMessage = null;
+        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
+        if (response.IsSuccessStatusCode)
+        {
+            var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+            formMessage = $"Shipment {created?.TrackingNumber} created successfully!";
+            showNewForm = false;
+            await LoadShipments();
+        }
+        else
+        {
+            formMessage = "Failed to create shipment. Please check all fields.";
+        }
+        isSubmitting = false;
+    }
+
+    private async Task UpdateStatus(int id, ChangeEventArgs e)
+    {
+        if (int.TryParse(e.Value?.ToString(), out var statusValue))
+        {
+            var status = (ShipmentStatus)statusValue;
+            await Http.PutAsJsonAsync($"/api/shipments/{id}/status",
