@page "/my-shipments"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>My Shipments</PageTitle>

<div class="container mt-4">
    <h2 class="mb-4">📋 My Shipments</h2>

    <div class="mb-3">
        <input type="text" class="form-control w-50" placeholder="Search by tracking # or destination..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    @if (shipments is null)
    {
        <p><em>Loading your shipments...</em></p>
    }
    else if (!shipments.Any())
    {
        <div class="alert alert-info">
            You don't have any shipments yet. Contact us or ask your dispatcher to assign shipments to your account.
        </div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var s in FilteredShipments)
            {
                <div class="col-md-6 col-lg-4">
                    <div class="card h-100 @GetCardBorder(s.Status)">
                        <div class="card-header d-flex justify-content-between align-items-center">
                            <strong>@s.TrackingNumber</strong>
                            <span class="badge @GetStatusBadge(s.Status)">@s.Status</span>
                        </div>
                        <div class="card-body">
                            <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                            <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                            <p class="mb-1"><strong>Recipient:</strong> @s.RecipientName</p>
                            <hr />
                            <p class="mb-1"><strong>Shipped:</strong> @s.ShippedDate.ToString("MMM dd, yyyy")</p>
                            <p class="mb-1">
                                <strong>Est. Delivery:</strong>
                                <span class="@(s.EstimatedDelivery < DateTime.UtcNow && s.Status != ShipmentStatus.Delivered ? "text-danger fw-bold" : "")">
                                    @s.EstimatedDelivery.ToString("MMM dd, yyyy")
                                </span>
                            </p>
                            @if (s.ActualDelivery.HasValue)
                            {
                                <p class="mb-1 text-success">
                                    <strong>Delivered:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy")
                                </p>
                            }
                            @if (!string.IsNullOrWhiteSpace(s.Notes))
                            {
                                <p class="mb-0 mt-2 text-muted small">📝 @s.Notes</p>
                            }
                        </div>
                        <div class="card-footer">
                            <div class="progress" style="height: 8px;">
                                <div class="progress-bar @GetProgressColor(s.Status)"
                                     role="progressbar"
                                     style="width: @(GetProgressPercent(s.Status))%">
                                </div>
                            </div>
                            <small class="text-muted mt-1 d-block">@GetProgressLabel(s.Status)</small>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    private List<ShipmentDto>? shipments;
    private string searchText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            string.IsNullOrWhiteSpace(searchText) ||
            s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetCardBorder(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "border-success",
        ShipmentStatus.Delayed => "border-danger",
        ShipmentStatus.OutForDelivery => "border-warning",
        _ => ""
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Returned => 100,
        _ => 0
    };

    private static string GetProgressColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-primary"
    };

    private static string GetProgressLabel(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Awaiting pickup",
        ShipmentStatus.PickedUp => "Package picked up",
        ShipmentStatus.InTransit => "In transit to destination",
        ShipmentStatus.OutForDelivery => "Out for delivery today",
        ShipmentStatus.Delivered => "Delivered ✓",
        ShipmentStatus.Delayed => "Delayed — check back soon",
        ShipmentStatus.Returned => "Returned to sender",
        _ => ""
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2 class="mb-4">🔍 Track a Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g. ST-100001)"
                       @bind="trackingNumber" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
                    @(isSearching ? "Searching..." : "Track")
                </button>
            </div>
        </div>
    </div>

    @if (notFound)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment with tracking number "<strong>@searchedNumber</strong>" was found.
            Please check the number and try again.
        </div>
    }

    @if (result is not null)
    {
        <div class="card border-0 shadow">
            <div class="card-header bg-dark text-white d-flex justify-content-between">
                <span>Tracking: <strong>@result.TrackingNumber</strong></span>
                <span class="badge @GetStatusBadge(result.Status) fs-6">@result.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <h5>Shipment Details</h5>
                        <table class="table table-borderless">
                            <tbody>
                                <tr><td class="fw-bold">From</td><td>@result.Origin</td></tr>
                                <tr><td class="fw-bold">To</td><td>@result.Destination</td></tr>
                                <tr><td class="fw-bold">Recipient</td><td>@result.RecipientName</td></tr>
                                <tr><td class="fw-bold">Shipped</td><td>@result.ShippedDate.ToString("MMMM dd, yyyy")</td></tr>
                            </tbody>
                        </table>
                    </div>
                    <div class="col-md-6">
                        <h5>Delivery Information</h5>
                        <table class="table table-borderless">
                            <tbody>
                                <tr>
                                    <td class="fw-bold">Estimated Delivery</td>
                                    <td>
                                        <span class="@(result.EstimatedDelivery < DateTime.UtcNow && result.Status != ShipmentStatus.Delivered ? "text-danger fw-bold" : "")">
                                            @result.EstimatedDelivery.ToString("MMMM dd, yyyy")
                                        </span>
                                    </td>
                                </tr>
                                @if (result.ActualDelivery.HasValue)
                                {
                                    <tr>
                                        <td class="fw-bold">Actual Delivery</td>
                                        <td class="text-success fw-bold">@result.ActualDelivery.Value.ToString("MMMM dd, yyyy")</td>
                                    </tr>
                                }
                                @if (!string.IsNullOrWhiteSpace(result.Notes))
                                {
                                    <tr><td class="fw-bold">Notes</td><td>@result.Notes</td></tr>
                                }
                            </tbody>
                        </table>
                    </div>
                </div>

                <!-- Progress tracker -->
                <div class="mt-4">
                    <h5>Shipment Progress</h5>
                    <div class="d-flex justify-content-between position-relative mt-3 mb-2">
                        @foreach (var step in progressSteps)
                        {
                            var isActive = IsStepActive(result.Status, step.Status);
                            var isCurrent = result.Status == step.Status;
                            <div class="text-center" style="flex: 1;">
                                <div class="rounded-circle mx-auto d-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted")"
                                     style="width: 40px; height: 40px; border: 2px solid @(isActive ? "#198754" : "#dee2e6");">
                                    @(isActive ? "✓" : step.Icon)
                                </div>
                                <small class="d-block mt-1 @(isCurrent ? "fw-bold" : "text-muted")">@step.Label</small>
                            </div>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? result;
    private bool notFound;
    private bool isSearching;

    private record ProgressStep(string Icon, string Label, ShipmentStatus Status);
    private readonly ProgressStep[] progressSteps =
    [
        new("📝", "Pending", ShipmentStatus.Pending),
        new("📦", "Picked Up", ShipmentStatus.PickedUp),
        new("🚛", "In Transit", ShipmentStatus.InTransit),
        new("🏠", "Out for Delivery", ShipmentStatus.OutForDelivery),
        new("✅", "Delivered", ShipmentStatus.Delivered)
    ];

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        notFound = false;
        result = null;
        searchedNumber = trackingNumber.Trim();

        var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(searchedNumber)}");
        if (response.IsSuccessStatusCode)
            result = await response.Content.ReadFromJsonAsync<ShipmentDto>();
        else
            notFound = true;

        isSearching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static bool IsStepActive(ShipmentStatus current, ShipmentStatus step)
    {
        if (current == ShipmentStatus.Delayed || current == ShipmentStatus.Returned)
            return false;
        return (int)current >= (int)step;
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

